// OpenCode V2 server-plugin entrypoint for this package.
//
// OpenCode resolves a plugin directory by probing `<dir>/server`, `<dir>/index`,
// and `<dir>/tui` as plain filesystem paths — a package.json `exports` subpath is
// NOT consulted for that probe, which is why the directory reports no id/version
// without this file. The documented local-plugin layout is `<dir>/index.ts`;
// this is the compiled equivalent, and `tui.js` next to it is the CLI entrypoint.
export { default } from "./dist/plugin.js"

export { createAutoRetrieveHook } from "./auto-retrieve";
export { distillRules } from "./auto-distill";
export { extractSessionLessons } from "./lesson-extraction";
export { captureSessionWork } from "./work-capture";
export { predictiveRateToolCall, applyScoreDecay } from "./predictive-rating";
export { runConsolidation } from "./consolidation";
export { searchNodes } from "./search";

import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import { createApplication } from "../infrastructure/composition-root";
import { withMcpLogging, mcpLog } from "./logging";
import { nodeToPlain, ensureScope, resourceStats } from "./transform";
import { VERSION } from "../version";
import { executeGraphTool } from "../tools/graph";
import { TOOL_INSTRUCTIONS } from "../tools/tool-instructions";
let store;
async function handleSearch(args) {
    const q = args.query?.trim();
    if (!q)
        return { content: [{ type: "text", text: "[]" }] };
    const scope = args.scope ?? "project";
    const limit = args.limit ?? 50;
    const projectName = args.project_name;
    try {
        const mode = args.search_mode ?? "hybrid";
        const { generateEmbedding } = await import("../infrastructure/llm/embeddings");
        const { searchNodes } = await import("../application/search");
        const opts = {
            limit,
            mode,
            scope,
        };
        if (projectName !== undefined)
            opts.projectName = projectName;
        const nodes = await searchNodes(store, generateEmbedding, q, opts);
        return { content: [{ type: "text", text: JSON.stringify(nodes.map(r => nodeToPlain(r.node)), null, 2) }] };
    }
    catch (e) {
        return {
            content: [{ type: "text", text: `Error: ${e instanceof Error ? e.message : String(e)}` }],
            isError: true,
        };
    }
}
export async function createMemoryMcpServer(projectDir, globalDbPath) {
    mcpLog("info", "Creating memory store", { projectDir });
    const ctx = await createApplication(projectDir, globalDbPath);
    store = ctx.store;
    mcpLog("info", "Memory store created");
    const server = new McpServer({ name: "opencode-fractal-memory", version: VERSION }, { capabilities: { tools: {}, resources: {} } });
    server.registerTool("memory", {
        description: TOOL_INSTRUCTIONS.mcp_memory.description,
        inputSchema: {
            mode: z.enum(["search", "get", "fetch", "list", "stats", "set", "delete"]).describe(TOOL_INSTRUCTIONS.mcp_memory.args.mode),
            // shared params
            scope: z.enum(["global", "project"]).optional().default("project"),
            project_name: z.string().optional(),
            // search params
            query: z.string().optional().describe(TOOL_INSTRUCTIONS.mcp_memory.args.query),
            search_mode: z.enum(["hybrid", "bm25", "text"]).optional().default("hybrid").describe(TOOL_INSTRUCTIONS.mcp_memory.args.search_mode),
            // get/fetch params
            id: z.string().optional().describe(TOOL_INSTRUCTIONS.mcp_memory.args.id),
            label: z.string().optional().describe(TOOL_INSTRUCTIONS.mcp_memory.args.label),
            // list params
            level: z.number().int().min(0).max(4).optional().describe(TOOL_INSTRUCTIONS.mcp_memory.args.level),
            type: z.string().optional().describe(TOOL_INSTRUCTIONS.mcp_memory.args.type),
            limit: z.number().int().positive().optional().default(100).describe(TOOL_INSTRUCTIONS.mcp_memory.args.limit),
            offset: z.number().int().nonnegative().optional().default(0).describe(TOOL_INSTRUCTIONS.mcp_memory.args.offset),
            // set params
            content: z.string().optional().describe(TOOL_INSTRUCTIONS.mcp_memory.args.content),
            importance: z.number().min(0).max(1).optional().default(0.5).describe(TOOL_INSTRUCTIONS.mcp_memory.args.importance),
            metadata: z.string().optional().describe(TOOL_INSTRUCTIONS.mcp_memory.args.metadata),
        },
    }, withMcpLogging("memory", async (args) => {
        const mode = args.mode;
        try {
            switch (mode) {
                case "search":
                    return await handleSearch(args);
                case "get": {
                    const node = await store.getNode(args.id);
                    return { content: [{ type: "text", text: JSON.stringify(nodeToPlain(node), null, 2) }] };
                }
                case "fetch": {
                    const node = await store.getNodeByLabel(ensureScope(args.scope), args.label);
                    return { content: [{ type: "text", text: JSON.stringify(nodeToPlain(node), null, 2) }] };
                }
                case "list": {
                    let nodes = await store.listNodes(args.scope, args.level, undefined, undefined, undefined, args.project_name);
                    if (args.type)
                        nodes = nodes.filter(n => n.type === args.type);
                    const total = nodes.length;
                    if (args.offset > 0)
                        nodes = nodes.slice(args.offset);
                    if (args.limit)
                        nodes = nodes.slice(0, args.limit);
                    return {
                        content: [{ type: "text", text: JSON.stringify({ total, nodes: nodes.map(n => nodeToPlain(n)) }, null, 2) }],
                    };
                }
                case "stats": {
                    const [stats, nodes] = await Promise.all([
                        store.getFractalStats(args.scope, args.project_name),
                        store.listNodes(args.scope, undefined, undefined, undefined, undefined, args.project_name),
                    ]);
                    const total = stats.totalNodes;
                    const avgImportance = total > 0 ? nodes.reduce((s, n) => s + n.importance, 0) / total : 0;
                    const avgUsefulness = total > 0 ? nodes.reduce((s, n) => s + (n.usefulnessScore ?? 0), 0) / total : 0;
                    const stickyCount = nodes.filter(n => n.sticky).length;
                    const types = {};
                    for (const n of nodes) {
                        const t = n.type ?? "unknown";
                        types[t] = (types[t] ?? 0) + 1;
                    }
                    return {
                        content: [{
                                type: "text",
                                text: JSON.stringify({
                                    scope: args.scope,
                                    totalNodes: total,
                                    nodesPerLevel: stats.nodesPerLevel,
                                    nodesPerType: types,
                                    avgImportance: Math.round(avgImportance * 100) / 100,
                                    avgUsefulness: Math.round(avgUsefulness * 100) / 100,
                                    totalAccessCount: nodes.reduce((s, n) => s + n.accessCount, 0),
                                    stickyCount,
                                }, null, 2),
                            }],
                    };
                }
                case "set": {
                    const scope = ensureScope(args.scope);
                    let metadata = null;
                    if (args.metadata) {
                        try {
                            metadata = JSON.parse(args.metadata);
                        }
                        catch {
                            return {
                                content: [{ type: "text", text: JSON.stringify({ success: false, error: "metadata must be valid JSON" }) }],
                                isError: true,
                            };
                        }
                    }
                    const existing = await store.getNodeByLabel(scope, args.label).catch(() => null);
                    if (existing) {
                        await store.updateNode(existing.id, {
                            content: args.content ?? existing.content,
                            level: args.level ?? existing.level,
                            type: args.type ?? existing.type,
                            importance: args.importance ?? existing.importance,
                            metadata: metadata ?? existing.metadata,
                        });
                        return { content: [{ type: "text", text: JSON.stringify({ success: true, id: existing.id, action: "updated" }) }] };
                    }
                    const created = await store.createNode({
                        scope,
                        label: args.label,
                        content: args.content ?? "",
                        level: args.level ?? 0,
                        type: args.type ?? null,
                        importance: args.importance ?? 0.5,
                        metadata,
                        projectName: args.project_name ?? store.projectName,
                    });
                    return { content: [{ type: "text", text: JSON.stringify({ success: true, id: created.id, action: "created" }) }] };
                }
                case "delete": {
                    const node = await store.getNode(args.id).catch(() => null);
                    if (!node) {
                        return { content: [{ type: "text", text: JSON.stringify({ success: false, error: "Node not found" }) }], isError: true };
                    }
                    await store.deleteNode(args.id);
                    return { content: [{ type: "text", text: JSON.stringify({ success: true, id: args.id, action: "deleted" }) }] };
                }
                default:
                    return { content: [{ type: "text", text: `Unknown mode: ${mode}` }], isError: true };
            }
        }
        catch (e) {
            const msg = e instanceof Error ? e.message : String(e);
            if (msg.includes("not found")) {
                return { content: [{ type: "text", text: "Node not found" }], isError: true };
            }
            return { content: [{ type: "text", text: `Error: ${msg}` }], isError: true };
        }
    }));
    // ==================== Expand Tool (stashed output) ====================
    const { createExpandTool } = await import("../tools/expand");
    const expandTool = createExpandTool();
    server.registerTool("expand", {
        description: expandTool.description ?? "Retrieve stashed tool output",
        inputSchema: (expandTool.args ?? {}),
    }, withMcpLogging("expand", async (args) => {
        const exec = expandTool.execute;
        if (!exec)
            return { content: [{ type: "text", text: "expand tool not available" }], isError: true };
        const res = await exec(args, {});
        return { content: [{ type: "text", text: String(res) }] };
    }));
    // ==================== Graph Tool ====================
    server.registerTool("graph", {
        description: TOOL_INSTRUCTIONS.mcp_graph.description,
        inputSchema: {
            relation: z.enum(["callers", "callees", "call_chain", "imports", "dependents", "search", "explain", "path"]).describe(TOOL_INSTRUCTIONS.mcp_graph.args.relation),
            name: z.string().optional().describe(TOOL_INSTRUCTIONS.mcp_graph.args.name),
            file: z.string().optional().describe(TOOL_INSTRUCTIONS.mcp_graph.args.file),
            depth: z.number().int().min(1).max(10).optional().describe(TOOL_INSTRUCTIONS.mcp_graph.args.depth),
            query: z.string().optional().describe(TOOL_INSTRUCTIONS.mcp_graph.args.query),
            from: z.string().optional().describe(TOOL_INSTRUCTIONS.mcp_graph.args.from),
            to: z.string().optional().describe(TOOL_INSTRUCTIONS.mcp_graph.args.to),
            id: z.string().optional().describe(TOOL_INSTRUCTIONS.mcp_graph.args.id),
            limit: z.number().int().positive().optional().describe(TOOL_INSTRUCTIONS.mcp_graph.args.limit),
        },
    }, withMcpLogging("graph", async (args) => {
        const result = executeGraphTool(args);
        return { content: [{ type: "text", text: JSON.stringify(result, null, 2) }] };
    }));
    server.registerResource("Memory Stats (project)", "memory://stats/project", { description: "Memory statistics for project scope" }, async (uri) => {
        mcpLog("info", "resource:read", { uri: uri.href });
        return { contents: [{ uri: uri.href, text: await resourceStats("project", store), mimeType: "application/json" }] };
    });
    server.registerResource("Memory Stats (global)", "memory://stats/global", { description: "Memory statistics for global scope" }, async (uri) => {
        mcpLog("info", "resource:read", { uri: uri.href });
        return { contents: [{ uri: uri.href, text: await resourceStats("global", store), mimeType: "application/json" }] };
    });
    return server;
}

import { readFileSync } from "node:fs";
import path from "node:path";
import { createApplication, createAutoRetrieve, scheduleBackgroundEmbeddings, startApplicationBackground, } from "../infrastructure/composition-root";
import { createHookHandlers } from "./hooks";
import { createToolMap } from "./tools";
import { memLog, perfNow } from "../logging";
import { resetInjectionLedger } from "../application/injection-visibility";
import { stopManagementServer, ensureManagementServer } from "../management-server";
import { setupJournal } from "./init";
import { createJournalStore } from "../application/journal";
import { ToastService } from "../infrastructure/toast-service";
import { incrementTurn } from "../application/re-read-elimination";
import { registerPlugin, resolveProjectDirectory } from "./registration";
import { createSessionApi } from "./session-api";
// Read the plugin version from the installed package.json next to dist/ (covers
// both the repo layout and the plugin-cache copy OpenCode actually loads).
// At runtime import.meta.dir = <pkg>/dist/plugin → two levels up is <pkg>/.
function loadPluginVersion() {
    try {
        const pkgPath = path.join(import.meta.dir, "..", "..", "package.json");
        const raw = readFileSync(pkgPath, "utf8");
        const pkg = JSON.parse(raw);
        return pkg.version ?? "unknown";
    }
    catch {
        return "unknown";
    }
}
/**
 * Shared, per-location core.
 *
 * A globally registered plugin serves EVERY project, so one process can host
 * several locations. Cores are memoized by resolved directory: each location
 * gets its own store/config/handlers, and closing one never touches another's
 * memory scope. Reference counting keeps a shared location alive while more
 * than one plugin setup still holds it.
 */
const cores = new Map();
function locationKey(directory) {
    return path.resolve(directory);
}
function getCore(directory, session) {
    const key = locationKey(directory);
    const existing = cores.get(key);
    if (existing) {
        existing.refs++;
        return existing.core;
    }
    const entry = { core: createCore(directory, session), refs: 1 };
    entry.core.catch(() => {
        if (cores.get(key) === entry)
            cores.delete(key);
    });
    cores.set(key, entry);
    return entry.core;
}
async function releaseCore(directory) {
    const key = locationKey(directory);
    const entry = cores.get(key);
    if (!entry)
        return;
    entry.refs--;
    if (entry.refs > 0)
        return;
    cores.delete(key);
    try {
        const core = await entry.core;
        await core.dispose();
    }
    catch {
        // init never completed — nothing to dispose
    }
    if (cores.size === 0)
        stopManagementServer();
}
async function createCore(directory, session) {
    const t0 = perfNow();
    memLog("info", "init", "Plugin initialization started", { directory });
    memLog("info", "TestLogging", "PLUGIN_LOADED_FROM", {
        resolvedDir: import.meta.dir,
        entryFile: import.meta.path,
        version: loadPluginVersion(),
    });
    let t = perfNow();
    let store;
    let memConfig;
    let app;
    try {
        // Heavy, optional subsystems are deferred: setup() must return before
        // OpenCode's background service health check times out.
        app = await createApplication(directory, undefined, { deferBackground: true });
        store = app.store;
        memConfig = app.memConfig;
        memLog("info", "init", "Application context created", { durationMs: perfNow() - t });
    }
    catch (err) {
        memLog("error", "init", "createApplication failed", {
            error: err instanceof Error ? err.message : String(err),
            stack: err instanceof Error ? err.stack : undefined,
        });
        throw err;
    }
    const ruleCache = new Map();
    const ruleCacheDirty = { value: true };
    const sessionInjectionLock = new Map();
    const latestUserMessage = { value: "" };
    t = perfNow();
    scheduleBackgroundEmbeddings(store);
    startApplicationBackground(app, directory);
    memLog("info", "init", "Background initialization scheduled", { durationMs: perfNow() - t });
    t = perfNow();
    const journalTools = await setupJournal(directory, memConfig);
    const journalStore = memConfig.journal?.enabled ? createJournalStore() : null;
    const journalCtx = { directory, model: "", provider: "" };
    memLog("info", "init", "Journal setup completed", { durationMs: perfNow() - t });
    const currentSessionId = { value: "" };
    const autoRetrieveHook = createAutoRetrieve(store, memConfig, session, currentSessionId);
    // Shared ToastService — callable from the tool factory, hooks, and any other
    // component that needs to surface a UI notification.
    const toastService = new ToastService(session, {
        enabled: memConfig.contextCompression?.enabled ?? true,
        mode: memConfig.contextCompression?.notificationMode ?? "chat",
    });
    // Shared per-session compress state is module-level in
    // application/context-compression/state.ts — both the tool factory and the
    // transform handler import it directly (no threading needed).
    const handlers = createHookHandlers(store, session, memConfig, ruleCache, ruleCacheDirty, sessionInjectionLock, latestUserMessage, { start: ensureManagementServer, stop: stopManagementServer }, currentSessionId, directory);
    const toolMap = createToolMap(store, journalTools, session, journalStore, journalCtx, memConfig, toastService, directory);
    memLog("info", "init", "Plugin initialization completed", { totalDurationMs: perfNow() - t0 });
    const composedMessage = async (event) => {
        currentSessionId.value = event.sessionID;
        incrementTurn();
        memLog("info", "live-capture", "composedMessage called", {
            sessionID: event.sessionID,
            hasHandler: !!handlers["message"],
        });
        await handlers["message"]?.(event);
    };
    const capturedMessageCounts = new Map();
    const turnIndexCounters = new Map();
    function nextTurnIndex(sessionId) {
        const cur = turnIndexCounters.get(sessionId) ?? 0;
        turnIndexCounters.set(sessionId, cur + 1);
        return cur;
    }
    const composedMessagesTransform = async (event) => {
        const messages = event.messages;
        const sid = currentSessionId.value;
        if (sid && messages && messages.length > 0) {
            const sysText = messages
                .filter((m) => m.role === "system")
                .map((m) => (m.parts || []).map((p) => p.text || "").join(" "))
                .join("\n");
            memLog("debug", "tool-map", "SYSTEM-PROMPT-TOOL-SCAN", {
                sysLen: sysText.length,
                roles: [...new Set(messages.map((m) => m.role ?? "?"))].join(","),
                sysHasArchivecontext: sysText.includes("archivecontext"),
                sysHasCompress: sysText.includes("compress"),
                sysHasMemory: sysText.includes("memory"),
                sysHasSkeletonize: sysText.includes("skeletonize"),
                sysHasGraph: sysText.includes("graph"),
            });
        }
        resetInjectionLedger();
        if (sid && messages && messages.length > 0) {
            const lastCount = capturedMessageCounts.get(sid) ?? 0;
            if (messages.length > lastCount) {
                const newMessages = messages.slice(lastCount);
                for (const msg of newMessages) {
                    const role = msg.role;
                    if (role !== "user" && role !== "assistant")
                        continue;
                    const partText = (msg.parts || []).map((p) => p.text || "").join("");
                    const fullContent = partText;
                    if (!fullContent)
                        continue;
                    try {
                        await store.recordConversationTurn({
                            sessionId: sid,
                            timestamp: Date.now(),
                            turnIndex: nextTurnIndex(sid),
                            role,
                            content: fullContent,
                            tokenCount: Math.round(fullContent.length / 4),
                        });
                        memLog("debug", "live-capture", `Captured ${role} from messages.transform`, { sessionId: sid, textLen: fullContent.length });
                    }
                    catch (e) {
                        memLog("error", "live-capture", `Failed to capture ${role}`, { error: String(e) });
                    }
                }
                capturedMessageCounts.set(sid, messages.length);
            }
        }
        await autoRetrieveHook?.["messages"]?.(event);
        await handlers["messages"]?.(event);
    };
    const dispose = async () => {
        await store.close();
    };
    return {
        handlers,
        toolMap,
        composedMessage,
        composedMessagesTransform,
        dispose,
    };
}
/**
 * Plugin entrypoint.
 *
 * The plugin registers its hooks on the domain that owns the operation and
 * the tool map on the tool registry.
 */
async function setupPlugin(ctx) {
    const directory = resolveProjectDirectory(ctx.location);
    const session = createSessionApi(ctx);
    const core = await getCore(directory, session);
    let released = false;
    return registerPlugin(ctx, {
        handlers: {
            ...core.handlers,
            "message": core.composedMessage,
            "messages": core.composedMessagesTransform,
        },
        toolMap: core.toolMap,
        dispose: async () => {
            if (released)
                return;
            released = true;
            await releaseCore(directory);
        },
    });
}
/**
 * Plugin entrypoint.
 *
 * The runtime loads the package directory, resolves the `index` entrypoint to
 * this module, and calls `setup(ctx)` once per location.
 */
export default {
    id: "opencode-fractal-memory",
    setup: setupPlugin,
};

